export interface ResponsePayload {status: number; body: string}
export interface Transport {request(url: string): Promise<ResponsePayload>}
export class FetchTransport implements Transport {
  async request(url: string): Promise<ResponsePayload> {
    const response = await fetch(url);
    return {status: response.status, body: await response.text()};
  }
}
export class Client {
  baseUrl: string;
  transport: Transport;
  constructor(baseUrl: string, transport: Transport = new FetchTransport()) {
    this.baseUrl = baseUrl;
    this.transport = transport;
  }
  async get(path: string): Promise<ResponsePayload> {
    return this.transport.request(this.baseUrl + "/" + path);
  }
}
